n//   END IF;\n//   RETURN NEW;\n// END;\n// $$ LANGUAGE plpgsql;\n//\n// Migration: CREATE TRIGGER enforce_role_market_match\n// BEFORE INSERT OR UPDATE ON user_roles\n// FOR EACH ROW EXECUTE FUNCTION enforce_role_market_match();\n\n// Migration: CREATE OR REPLACE FUNCTION enforce_cheque_tenant_market_match()\n// RETURNS TRIGGER AS $$\n// BEGIN\n//   IF NOT EXISTS (\n//     SELECT 1 FROM market_tenants\n//     WHERE tenant_id = NEW.tenant_id AND market_id = NEW.market_id AND deleted_at IS NULL\n//   ) THEN\n//     RAISE EXCEPTION 'Cheque.tenantId and marketId must correspond to an active MarketTenant entry';\n//   END IF;\n//   RETURN NEW;\n// END;\n// $$ LANGUAGE plpgsql;\n//\n// Migration: CREATE TRIGGER enforce_cheque_tenant_market_match\n// BEFORE INSERT OR UPDATE ON cheques\n// FOR EACH ROW EXECUTE FUNCTION enforce_cheque_tenant_market_match();\n\n// Migration: CREATE OR REPLACE FUNCTION enforce_maintenance_tenant_market_match()\n// RETURNS TRIGGER AS $$\n// BEGIN\n//   IF NOT EXISTS (\n//     SELECT 1 FROM market_tenants\n//     WHERE tenant_id = NEW.tenant_id AND market_id = NEW.market_id AND deleted_at IS NULL\n//   ) THEN\n//     RAISE EXCEPTION 'MaintenanceRequest.tenantId and marketId must correspond to an active MarketTenant entry';\n//   END IF;\n//   RETURN NEW;\n// END;\n// $$ LANGUAGE plpgsql;\n//\n// Migration: CREATE TRIGGER enforce_maintenance_tenant_market_match\n// BEFORE INSERT OR UPDATE ON maintenance_requests\n// FOR EACH ROW EXECUTE FUNCTION enforce_maintenance_tenant_market_match();\n\n// Migration: CREATE OR REPLACE FUNCTION enforce_expense_employee_market_match()\n// RETURNS TRIGGER AS $$\n// BEGIN\n//   IF NEW.employee_id IS NOT NULL THEN\n//     IF NOT EXISTS (\n//       SELECT 1 FROM market_employees\n//       WHERE employee_id = NEW.employee_id AND market_id = NEW.market_id AND is_active = true AND deleted_at IS NULL\n//     ) THEN\n//       RAISE EXCEPTION 'MarketExpense.employeeId must belong to an active MarketEmployee in the same