// FIXED: Added JournalLine immutability trigger (ACT-03)\n// REASON: The journal_entries trigger protects the header; this protects the lines\n// Migration: CREATE OR REPLACE FUNCTION enforce_journal_line_immutability()\n// RETURNS TRIGGER AS $$\n// DECLARE\n//   je_status journal_entries.status%TYPE;\n// BEGIN\n//   IF TG_OP = 'DELETE' THEN\n//     SELECT status INTO je_status FROM journal_entries WHERE id = OLD.journal_id;\n//   ELSE\n//     SELECT status INTO je_status FROM journal_entries WHERE id = NEW.journal_id;\n//   END IF;\n//   IF je_status = 'POSTED' THEN\n//     RAISE EXCEPTION 'Journal lines on a POSTED entry are immutable. Void the entry to reverse.';\n//   END IF;\n//   IF je_status = 'VOID' THEN\n//     RAISE EXCEPTION 'Journal lines on a VOID entry are fully immutable.';\n//   END IF;\n//   IF TG_OP = 'DELETE' THEN\n//     RETURN OLD;\n//   ELSE\n//     RETURN NEW;\n//   END IF;\n// END;\n// $$ LANGUAGE plpgsql;\n//\n// Migration: CREATE TRIGGER trg_journal_line_immutability\n// BEFORE INSERT OR UPDATE OR DELETE ON journal_lines\n// FOR EACH ROW EXECUTE FUNCTION enforce_journal_line_immutability();\n\n// FIXED: Added journal entry balance enforcement trigger (ACT-02)\n// REASON: Double-entry accounting requires SUM(debit) = SUM(credit) per entry\n// This trigger fires after any JournalLine change and validates balance for POSTED entries\n// Migration: CREATE OR REPLACE FUNCTION enforce_journal_balance()\n// RETURNS TRIGGER AS $$\n// DECLARE\n//   je_status journal_entries.status%TYPE;\n//   total_debit  NUMERIC;\n//   total_credit NUMERIC;\n//   target_journal_id UUID;\n// BEGIN\n//   IF TG_OP = 'DELETE' THEN\n//     target_journal_id := OLD.journal_id;\n//   ELSE\n//     target_journal_id := NEW.journal_id;\n//   END IF;\n//   SELECT status INTO je_status FROM journal_entries WHERE id = target_journal_id;\n//   -- Only enforce for POSTED entries (DRAFT entries are still being built)\n//   IF je_status = 'POSTED' THEN\n//     SELECT COALESCE(SUM(debit), 0), COALESCE(SUM(credit), 0)\n//       INTO total_debit, total_credit\n//       FROM journal_lines\n//       WHERE journal_id = target_journal_id;\n//     IF total_debit != total_credit THEN\n//       RAISE EXCEPTION 'Journal entry is unbalanced. Debit: %, Credit: %. POSTED entries must have balanced debits and credits.',\n//         total_debit, total_credit;\n//     END IF;\n//   END IF;\n//   IF TG_OP = 'DELETE' THEN\n//     RETURN OLD;\n//   ELSE\n//     RETURN NEW;\n//   END IF;\n// END;\n// $$ LANGUAGE plpgsql;\n//\n// Migration: CREATE TRIGGER trg_enforce_journal_balance\n// AFTER INSERT OR UPDATE OR DELETE ON journal_lines\n// FOR EACH ROW EXECUTE FUNCTION enforce_journal_balance();\n\n// --- EXCLUSION CONSTRAINTS ---\n\n// Migration: ALTER TABLE contracts ADD CONSTRAINT no_overlapping_contracts\n// EXCLUDE USING gist (shop_id WITH =, daterange(start_date, end_date, '[]') WITH &&)\n// WHERE (status IN ('ACTIVE'));\n\n// --- PARTITIONING ---\n\n// Migration: ALTER TABLE audit_logs PARTITION BY RANGE (created_at);\n// Migration: ALTER TABLE account_transactions PARTITION BY RANGE (transaction_date);\n",
